"""
Canonical definition of what counts as a produced artifact.

This module centralizes the logic for filtering out machine-generated directories
and malformed paths (e.g., those containing markdown artifacts) from agent
workspaces. This ensures consistent reporting across the runtime, verifier,
and analysis scripts.
"""

from typing import Dict, Tuple, Iterable

# Directories that are typically generated by tools, environments, or caches
# and should not be counted as agent-authored artifacts.
EXCLUDED_DIR_SEGMENTS = (
    '.pytest_cache',
    '__pycache__',
    'venv',
    '.venv',
    '.git',
    '.mypy_cache',
    '.ruff_cache',
    '.tox',
    'node_modules',
    '.ipynb_checkpoints'
)

# Suffixes for directories that indicate installed packages or build artifacts.
EXCLUDED_DIR_SUFFIXES = (
    '.egg-info',
    '.dist-info'
)


def is_generated_path(path: str) -> bool:
    """True if the path lives inside a machine-generated directory."""
    if not path:
        return False
    
    # Normalize separators to handle both unix and windows style paths if necessary
    # but primarily we look at segments.
    # We split by '/' and also handle potential backslashes if they appear in the string representation
    # though standard python paths usually use os.sep. The spec implies string paths.
    
    # Split by common separators
    parts = path.replace('\\', '/').split('/')
    
    for part in parts:
        if part in EXCLUDED_DIR_SEGMENTS:
            return True
        # Check for suffixes on directory parts (e.g., package.egg-info)
        # Note: The spec says "lives inside", so we check directory components.
        # The last part is the filename, which shouldn't be checked for dir suffixes 
        # unless it's a directory itself, but in a file bundle, the last part is a file.
        # However, if a path is "foo/bar.egg-info/baz.py", "bar.egg-info" is a dir segment.
        if any(part.endswith(suffix) for suffix in EXCLUDED_DIR_SUFFIXES):
            return True
            
    return False


def is_malformed_path(path: str) -> bool:
    """True if markdown formatting, stray whitespace, or invalid punctuation leaked into the filename.

    Agents emit paths through a ReAct text protocol, so bold markers (`*`),
    backticks (`` ` ``), leading/trailing whitespace, trailing dots (`.`) or
    tildes (`~`), or leading hyphens (`-`) periodically survive into `write_file`
    calls. The resulting files are unusable -- `routing.py**` or `notes.` is not
    valid -- so any path containing `*` or `` ` ``, leading/trailing whitespace,
    starting with `-`, or ending with `.` or `~` is malformed.
    """
    if not path:
        return True # Empty path is malformed? Or just invalid. Let's assume True as it's not a valid file.
    
    # Check for leading/trailing whitespace
    if path != path.strip():
        return True
        
    # Check for markdown characters anywhere in the path
    if '*' in path or '`' in path:
        return True
        
    # Check for leading hyphen
    if path.startswith('-'):
        return True
        
    # Check for trailing dot or tilde
    if path.endswith('.') or path.endswith('~'):
        return True
        
    return False


def sanitize_path(path: str) -> str:
    """Strips markdown decoration from an agent-supplied path.

    Applied at write time so the artifact lands at its intended location rather
    than being silently created with a broken name.
    """
    if not path:
        return path
        
    # Strip leading/trailing whitespace
    cleaned = path.strip()
    
    # Remove markdown bold/italic markers and backticks
    # We remove them entirely as they are decoration.
    cleaned = cleaned.replace('*', '')
    cleaned = cleaned.replace('`', '')
    
    # Remove leading hyphens if they are considered decoration? 
    # The spec says "leading hyphens ... periodically survive". 
    # Usually leading hyphens in filenames are valid (e.g. .gitignore, -file.txt).
    # However, the spec says "starting with -" makes it malformed.
    # Sanitization should likely remove the leading hyphen if it's considered an artifact.
    # Let's strip leading hyphens.
    while cleaned.startswith('-'):
        cleaned = cleaned[1:]
        
    # Remove trailing dots or tildes
    while cleaned.endswith('.') or cleaned.endswith('~'):
        cleaned = cleaned[:-1]
        
    return cleaned


def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
    """Returns only genuinely agent-authored files from a path->content map."""
    filtered = {}
    for path, content in bundle.items():
        if not is_generated_path(path) and not is_malformed_path(path):
            filtered[path] = content
    return filtered


def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
    """Splits a bundle into (authored, generated, malformed) for reporting."""
    authored = {}
    generated = {}
    malformed = {}
    
    for path, content in bundle.items():
        if is_generated_path(path):
            generated[path] = content
        elif is_malformed_path(path):
            malformed[path] = content
        else:
            authored[path] = content
            
    return authored, generated, malformed


def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
    """Counts authored files matching the given suffixes."""
    count = 0
    # We only count files that are NOT generated and NOT malformed
    for path in bundle.keys():
        if is_generated_path(path) or is_malformed_path(path):
            continue
            
        # Check if path ends with any of the suffixes
        # Note: suffixes might be like '.py', '.js'
        if any(path.endswith(suffix) for suffix in suffixes):
            count += 1
            
    return count